// Locator Lab scenarios. Pure data: every scenario has a goal, a DOM, a reference `target` (evaluated by the engine)
// and verified solutions in CSS, XPath and Playwright. A test runs every solution against real Playwright.
export const CATEGORIES = [
  ["css", "CSS selectors"],
  ["css-adv", "CSS: pseudo-classes & combinators"],
  ["xpath", "XPath basics & functions"],
  ["axes", "XPath axes"],
  ["pw", "Playwright built-in locators"],
  ["pw-chain", "Playwright chaining & filters"],
  ["tricky", "Tricky DOM"],
];
const fr = (html) => html.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
const MENU = `<ul class="menu"><li class="item">Home</li><li class="item active">Docs</li><li class="item active disabled">Blog</li><li class="item">Contact</li></ul>`;
const TABLE = `<table id="books"><caption>Books</caption><thead><tr><th>Title</th><th>Author</th><th>Price</th></tr></thead><tbody>
<tr><td>Clean Code</td><td>Robert Martin</td><td>32.00</td></tr>
<tr><td>Testing JavaScript</td><td>Kent Dodds</td><td>29.00</td></tr>
<tr><td>Continuous Delivery</td><td>Jez Humble</td><td>49.00</td></tr></tbody></table>`;
const LIST_ROWS = `<ul class="todo"><li><span>Alpha</span> <button>Delete</button></li><li><span>Beta</span> <button>Delete</button></li><li><span>Gamma</span> <button>Delete</button></li></ul>`;

